<!-- This file is generated by AI. -->

<!--
  配音工作台: 服务与启动配置、任务队列、角色库。

  它是工作区里的一个**独立页面** (打开时取代整个工作区, 不与选项卡混排), 因此不会出现
  "选项卡同时选中"或"切走就自动关闭"这类问题。

  两栏内的分组都做成**分页**, 而不是把所有字段堆成一长条: 字段一多就必须滚动, 而滚动会把
  "启动服务"这类关键操作推到视野之外。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { open as openDialog, save as saveDialog } from '@tauri-apps/plugin-dialog';
  import { revealItemInDir } from '@tauri-apps/plugin-opener';
  import { onMount } from 'svelte';

  import type { CondaEnv, LaunchConfig, LaunchMode } from '../commands/voice';
  import { fs } from '../lib/fs';
  import { actions, appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { formatDuration, formatEta } from '../voice/estimate';
  import { errorSummary } from '../voice/errorText';
  import { queueView } from '../voice/queue';
  import { LANGUAGE_LABELS, type VoiceTask } from '../voice/types';
  import Button from './Button.svelte';
  import Icon from './Icon.svelte';
  import PriorityButton from './PriorityButton.svelte';
  import RoleListPanel from './RoleListPanel.svelte';
  import Select from './Select.svelte';
  import TaskProgress from './TaskProgress.svelte';
  import VoiceCacheDialog from './VoiceCacheDialog.svelte';
  import VoiceErrorDialog from './VoiceErrorDialog.svelte';

  type ConfigPage = 'service' | 'defaults';
  type QueuePage = 'queue' | 'log';

  /** 服务状态与日志直接读 store 字段 (它们本身就是响应式的 `$state`)。 */
  const status = $derived(appStore.voiceStatus);
  const logs = $derived(appStore.voiceLogs);

  /** 启动配置草稿 (与设置里那一份同步) */
  let rootPath = $state('');
  let launch = $state<LaunchConfig | null>(null);
  let condaEnvs = $state<CondaEnv[]>([]);
  let busy = $state(false);
  let error = $state<string | null>(null);
  let configPage = $state<ConfigPage>('service');
  let queuePage = $state<QueuePage>('queue');
  let changeDialogOpen = $state(false);
  /** 正在查看失败详情的任务 (null 表示不显示弹窗) */
  let errorTask = $state<VoiceTask | null>(null);

  const settings = $derived.by(() => {
    void appStore.voiceTick;
    return voiceController.getSettings();
  });
  const defaults = $derived(settings.defaults);
  const summary = $derived.by(() => {
    void appStore.voiceTick;
    return voiceController.queueSummary();
  });

  /**
   * 队列的展示顺序。
   *
   * ⚠️ 这里有两件事缺一不可 (与 `VoiceTakeList.svelte` 同理):
   * 1. 自己读 `appStore.voiceTick` 并产出**新数组**: `voiceController.allTasks()` 返回的是
   *    控制器内部那个**同一个数组**, 而 `$derived` 用 `===` 比较新旧值, 值没变就不向下游传播 ——
   *    读在中间层上会让队列面板永远停在旧内容;
   * 2. **每一项再浅拷贝一层**: 键相同的行会被 `{#each}` 复用, 而 each 更新项同样按 `===` 判断,
   *    传同一个对象引用时不传播 —— 任务在跑时就地改的字段 (状态 / 已用 / 进度) 不会反映到行上。
   */
  const queue = $derived.by(() => {
    void appStore.voiceTick;
    return queueView(voiceController.allTasks()).map((task) => ({ ...task }));
  });

  /** 日志容器: 新日志到达时贴到底 (控制台的习惯) */
  let logHost = $state<HTMLDivElement | undefined>();

  $effect(() => {
    const count = logs.length;
    const host = logHost;
    void count;
    if (!host) return;
    // 只在日志页可见时才有意义 (切到日志页时 `logHost` 才被赋值, 于是这里会再跑一次)
    host.scrollTop = host.scrollHeight;
  });

  /*
   * `stopping` 也算"运行中": 停止过程中按钮必须留在"停止服务"这一态 (并禁用),
   * 否则它会闪回「启动服务」—— 用户很容易在服务还没停干净时又点一次启动。
   */
  const running = $derived(status === 'ready' || status === 'starting' || status === 'stopping');

  const statusLabel = $derived(
    status === 'ready'
      ? '就绪'
      : status === 'starting'
        ? '启动中…'
        : status === 'stopping'
          ? '停止中…'
          : status === 'error'
            ? '错误'
            : '未启动'
  );

  onMount(() => {
    const current = voiceController.getSettings();
    if (current.launch) {
      rootPath = current.launch.root;
      launch = current.launch;
    }
    // conda 环境列表在打开工作台时扫描一次 (扫描失败的常见原因是本机没有 conda)
    void voiceController.listCondaEnvs().then((envs) => (condaEnvs = envs));
  });

  /** 更新并持久化启动配置 */
  function patchLaunch(patch: Partial<LaunchConfig>): void {
    const current = launch;
    if (!current) return;
    const next = { ...current, ...patch };
    launch = next;
    voiceController.updateSettings({ launch: next });
  }

  /** 选择整合包目录并探测 */
  async function pickRoot(): Promise<void> {
    const selected = await openDialog({ directory: true, multiple: false, title: '选择 GPT-SoVITS 整合包目录' });
    if (typeof selected !== 'string') return;
    rootPath = selected;
    busy = true;
    error = null;
    try {
      const config = await voiceController.detect(selected);
      launch = config;
      voiceController.updateSettings({ launch: config });
    } catch (caught) {
      error = errorSummary(String(caught));
    } finally {
      busy = false;
    }
  }

  /**
   * 整合包目录按钮 (目录的唯一入口)。
   *
   * 尚未选择时点击进入选择; 已选择时点击在文件管理器中打开 —— 因此不需要额外的
   * 「选择…」按钮, 也就不会出现两个长得一样、含义却不同的文件夹图标。
   */
  function onRootAction(): void {
    if (rootPath) void revealItemInDir(rootPath);
    else void pickRoot();
  }

  /** 选择 Python 解释器文件 (仅「外部 Python」用) */
  async function pickProgram(): Promise<void> {
    if (!launch) return;
    const picked = await openDialog({
      multiple: false,
      title: '选择 Python 解释器',
      filters: [{ name: '可执行文件', extensions: ['exe'] }],
    });
    if (typeof picked !== 'string') return;
    patchLaunch({ mode: { kind: 'python', program: picked } });
  }

  async function start(): Promise<void> {
    if (!launch) {
      error = '请先选择 GPT-SoVITS 整合包目录';
      return;
    }
    busy = true;
    error = null;
    try {
      await voiceController.startGsv(launch);
    } catch (caught) {
      error = errorSummary(String(caught));
    } finally {
      busy = false;
    }
  }

  /*
   * 停止服务**不禁用**: 启动过程中最需要的能力就是"取消" —— 首次加载模型要几十秒,
   * 路径填错时要能立刻停下, 而不是干等它自己失败。
   */
  async function stop(): Promise<void> {
    busy = true;
    try {
      await voiceController.stopGsv();
    } finally {
      busy = false;
    }
  }

  /** 导出运行日志为文本文件 */
  async function exportLogs(): Promise<void> {
    const destination = await saveDialog({
      defaultPath: 'gsov-日志.txt',
      filters: [{ name: '文本文件', extensions: ['txt', 'log'] }],
    });
    if (typeof destination !== 'string') return;
    await fs.writeText(destination, logs.join('\n'));
  }

  /** 切换启动方式时的默认字段值 */
  function defaultMode(kind: string, current: LaunchConfig): LaunchMode {
    switch (kind) {
      case 'conda':
        return { kind: 'conda', env: '', program: null };
      case 'python':
        return { kind: 'python', program: 'python' };
      case 'command':
        return { kind: 'command', command: defaultCommand(current) };
      default:
        return { kind: 'embedded', program: `${current.root}\\runtime\\python.exe` };
    }
  }

  /**
   * 自定义命令的默认值: 直接给出"用整合包内置运行时跑它的控制脚本"这条等价命令。
   *
   * 这样切到自定义命令时拿到的是一个**已经能跑**的命令行 (路径已指向整合包),
   * 按需改一处即可; 而不是 `C:\gsov\start.bat` 那种要自己从零猜的示例。
   */
  function defaultCommand(current: LaunchConfig): string {
    const root = current.root.replace(/[\\/]+$/, '');
    return `"${root}\\runtime\\python.exe" "${root}\\${current.script}" -a ${current.host} -p ${current.port} -c ${current.inferConfig}`;
  }

  function modeLabel(current: LaunchConfig): string {
    switch (current.mode.kind) {
      case 'embedded':
        return '使用整合包自带的 runtime\\python.exe（自动加 -I 隔离）';
      case 'conda':
        return '通过 conda run 调用指定环境（等于先激活环境再执行，不加 -I）';
      case 'python':
        return '使用指定的 Python 解释器（不隔离）';
      default:
        return '整条命令原样执行，Ink 只负责启动与收尾';
    }
  }
</script>

<div class="voice-workbench">
  <!-- -------- 页头: 标题 + 主要操作 -------- -->
  <div class="voice-workbench-header">
    <div class="voice-workbench-heading">
      <h1>配音工作台</h1>
      <p>
        GPT-SoVITS 服务、角色库与任务队列
        <span class="workbench-status-{status}"> · {statusLabel}</span>
      </p>
    </div>
    <div class="voice-workbench-actions">
      {#if running}
        <Button
          appearance="danger-outline"
          icon="RecordStop"
          disabled={status === 'stopping'}
          onclick={() => void stop()}
        >
          {status === 'stopping' ? '停止中…' : '停止服务'}
        </Button>
      {:else}
        <Button appearance="primary" icon="Play" disabled={busy} onclick={() => void start()}>启动服务</Button>
      {/if}
      <Button icon="QuestionCircle" onclick={() => actions.openVoiceGuide()}>帮助</Button>
    </div>
  </div>

  <!--
    布局: 左上一 = 服务配置 (按内容高度), 左下一 = 角色库 (吃掉左栏剩余高度),
    右侧 = 运行状态 (占满整列高度)。
  -->
  <div class="voice-workbench-columns">
    <div class="voice-workbench-left">
      <section class="workbench-card">
        <div class="workbench-card-head">
          <h2 class="workbench-card-title">服务配置</h2>
          <div class="workbench-tabs">
            <button type="button" class:active={configPage === 'service'} onclick={() => (configPage = 'service')}>
              启动方式
            </button>
            <button type="button" class:active={configPage === 'defaults'} onclick={() => (configPage = 'defaults')}>
              合成设置
            </button>
          </div>
        </div>

        {#if configPage === 'service'}
          <label class="voice-field">
            <span class="voice-label">GPT-SoVITS 整合包目录</span>
            <div class="input-row">
              <input class="ui-input" value={rootPath} readonly placeholder="选择包含 api_v2.py 的整合包目录" />
              <Button
                icon="Folder"
                title={rootPath ? '在文件管理器中打开' : '选择整合包目录'}
                disabled={running || (busy && !rootPath)}
                onclick={onRootAction}
              />
            </div>
          </label>

          {#if launch}
            <div class="workbench-grid">
              <!--
              启动方式是"怎么把服务拉起来"的配置。服务一旦在跑 (启动中/就绪),
              这些字段全部锁定 —— 改了也不会作用到已启动的进程上, 只会让人以为
              改动生效了。想改就先停服务。
            -->
              <label class="voice-field">
                <span class="voice-label">启动方式</span>
                <Select
                  value={launch.mode.kind}
                  title={modeLabel(launch)}
                  disabled={running}
                  options={[
                    { value: 'embedded', label: '整合包运行时' },
                    { value: 'python', label: 'Python' },
                    { value: 'conda', label: 'Conda' },
                    { value: 'command', label: '自定义命令' },
                  ]}
                  onchange={(kind) => patchLaunch({ mode: defaultMode(kind, launch!) })}
                />
              </label>

              <!--
              按启动方式给出不同的第二项:
              * 内置运行时 -> 只读显示解释器路径 (由整合包决定, 不可改);
              * conda      -> 环境下拉 (从本机扫描), 没有文件夹图标;
              * 外部 Python -> 解释器路径 + 文件夹图标;
              * 自定义命令 -> 一整条命令 + 参数, 没有文件夹图标。
            -->
              {#if launch.mode.kind === 'embedded'}
                <label class="voice-field">
                  <span class="voice-label">Python 解释器</span>
                  <input class="ui-input" value={launch.mode.program} readonly title="由整合包内置运行时决定" />
                </label>
              {/if}

              {#if launch.mode.kind === 'conda'}
                <label class="voice-field">
                  <span class="voice-label">conda 运行环境</span>
                  <Select
                    value={launch.mode.env}
                    title="选择本机已安装的 conda 环境（通过 conda run 调用，与手动激活等价）"
                    placeholder={condaEnvs.length === 0 ? '未发现 conda 环境' : '选择环境'}
                    disabled={running}
                    options={condaEnvs.map((env) => ({ value: env.name, label: env.displayName }))}
                    onchange={(env) => patchLaunch({ mode: { kind: 'conda', env, program: null } })}
                  />
                </label>
              {/if}

              {#if launch.mode.kind === 'python'}
                <label class="voice-field">
                  <span class="voice-label">Python 解释器</span>
                  <div class="input-row">
                    <input
                      class="ui-input"
                      value={launch.mode.program}
                      disabled={running}
                      oninput={(event) => patchLaunch({ mode: { kind: 'python', program: event.currentTarget.value } })}
                    />
                    <Button
                      icon="Folder"
                      title="选择 Python 解释器"
                      disabled={running}
                      onclick={() => void pickProgram()}
                    />
                  </div>
                </label>
              {/if}

              {#if launch.mode.kind === 'command'}
                <label class="voice-field workbench-field-wide">
                  <span class="voice-label">命令</span>
                  <input
                    class="ui-input"
                    value={launch.mode.command}
                    placeholder="在这里直接写完整命令"
                    disabled={running}
                    oninput={(event) => patchLaunch({ mode: { kind: 'command', command: event.currentTarget.value } })}
                  />
                </label>
              {/if}

              {#if launch.mode.kind !== 'command'}
                <label class="voice-field">
                  <span class="voice-label">控制脚本</span>
                  <input
                    class="ui-input"
                    value={launch.script}
                    disabled={running}
                    oninput={(event) => patchLaunch({ script: event.currentTarget.value })}
                  />
                </label>

                <label class="voice-field">
                  <span class="voice-label">推理配置</span>
                  <input
                    class="ui-input"
                    value={launch.inferConfig}
                    disabled={running}
                    oninput={(event) => patchLaunch({ inferConfig: event.currentTarget.value })}
                  />
                </label>
              {/if}
            </div>
          {/if}
        {:else}
          <div class="workbench-grid">
            <label class="voice-field">
              <span class="voice-label">默认语言</span>
              <Select
                value={defaults.language}
                title="新对话默认使用的语言"
                options={Object.entries(LANGUAGE_LABELS).map(([value, label]) => ({ value, label }))}
                onchange={(language) => voiceController.updateSettings({ defaults: { ...defaults, language } })}
              />
            </label>
          </div>
        {/if}

        {#if error}
          <p class="voice-error">
            <Icon name="ErrorCircle" size={14} />
            <span>{error}</span>
          </p>
        {/if}
      </section>

      <!-- 角色库: 吃掉左栏剩余高度 (卡片内部列表自己滚动) -->
      <RoleListPanel />
    </div>

    <section class="workbench-card">
      <div class="workbench-card-head">
        <h2 class="workbench-card-title">运行状态</h2>
        <div class="workbench-tabs">
          <button type="button" class:active={queuePage === 'queue'} onclick={() => (queuePage = 'queue')}>队列</button>
          <button type="button" class:active={queuePage === 'log'} onclick={() => (queuePage = 'log')}>日志</button>
        </div>
        <span class="workbench-spacer"></span>
        {#if queuePage === 'log'}
          <Button
            appearance="bare"
            icon="ArrowClockwise"
            title="刷新日志"
            onclick={() => void voiceController.syncStatus()}
          />
          <Button
            appearance="bare"
            icon="ArrowDownload"
            title="导出日志"
            disabled={logs.length === 0}
            onclick={() => void exportLogs()}
          />
        {:else}
          <Button
            appearance="bare"
            icon="Wrench"
            title="清理未被任何场景引用的缓存音频"
            onclick={() => (changeDialogOpen = true)}
          />
          <Button
            appearance="bare"
            icon="Dismiss"
            title="清空已完成的任务"
            onclick={() => voiceController.clearFinishedTasks()}
          />
        {/if}
      </div>

      <p class="workbench-summary">
        待处理 {summary.pending}（测试 {summary.pendingTest} · 生成 {summary.pendingGenerate}）{#if summary.running > 0}
          · 运行中 {summary.running}{/if}{#if summary.pending + summary.running > 0}
          · 预计 {formatEta(summary.etaMillis)}{/if}
      </p>

      {#if queuePage === 'queue'}
        <div class="workbench-scroll">
          {#if queue.length === 0}
            <p class="voice-dialog-empty">队列为空。在场景卡的配音模式中点击「测试」或「生成」。</p>
          {/if}
          <!--
            展示顺序 = 运行中 -> 排队中(按真实执行顺序) -> 已结束(按结束时刻从新到旧)。
            见 `queueView`: 按入队顺序显示会让一条早就跑完的生成任务压在几条完成的
            测试任务上面, 看起来像还没跑。
          -->
          {#each queue as task (task.id)}
            <div class="voice-task {task.status}">
              <span class="history-kind {task.kind}">
                {task.kind === 'test' ? '测试' : '生成'} x{task.params.sampleSteps}
              </span>
              <span class="voice-task-text">{task.text || '（空）'}</span>
              <span class="voice-task-character">{task.characterName}</span>
              <span class="voice-task-status">
                {#if task.status === 'pending'}等待中{/if}
                {#if task.status === 'running'}生成中{/if}
                {#if task.status === 'done'}
                  已完成{task.elapsed !== undefined ? ` · 响应 ${formatDuration(task.elapsed)}` : ''}
                {/if}
                {#if task.status === 'failed'}失败{/if}
                {#if task.status === 'canceled'}已取消{/if}
              </span>
              <!-- 排队中可以改优先级 (单图标: 上=提升 / 下=降低), 未完成的都可以取消 -->
              {#if task.status === 'pending'}
                <PriorityButton
                  priority={task.priority}
                  onToggle={() =>
                    voiceController.setPriority(task.id, task.priority === 'immediate' ? 'normal' : 'immediate')}
                />
              {/if}
              {#if task.status === 'pending' || task.status === 'running'}
                <Button
                  appearance="bare"
                  icon="Dismiss"
                  title={task.status === 'running'
                    ? '取消（推理无法中断，返回后丢弃结果）'
                    : '取消（还没开始，直接撤下）'}
                  onclick={() => voiceController.cancel(task.id)}
                />
              {/if}
              {#if task.status === 'running'}
                <TaskProgress steps={task.params.sampleSteps} text={task.text} startedAt={task.startedAt} />
              {/if}
              {#if task.status === 'pending'}
                <TaskProgress steps={task.params.sampleSteps} text={task.text} />
              {/if}
              {#if task.status === 'failed' && task.error}
                <!--
                  报错只占一行 (整行独占, 见 `.voice-task-error`): 原文有几十行,
                  直接铺开会把整个任务项撑成一屏。点开弹窗看全文。
                -->
                <button
                  type="button"
                  class="error-chip voice-task-error"
                  title="查看完整报错"
                  onclick={() => (errorTask = task)}
                >
                  <span class="error-chip-icon"><Icon name="ErrorCircle" size={14} /></span>
                  <span class="error-chip-text">{errorSummary(task.error)}</span>
                  <span class="error-chip-more">详情</span>
                </button>
              {/if}
            </div>
          {/each}
        </div>
      {:else}
        <div class="workbench-scroll workbench-log" bind:this={logHost}>
          {#if logs.length === 0}
            <p class="voice-dialog-empty">暂无日志。</p>
          {/if}
          {#each logs as line, index (index)}
            <div class="voice-log-line">{line}</div>
          {/each}
        </div>
      {/if}
    </section>
  </div>

  {#if errorTask}
    <VoiceErrorDialog
      error={errorTask.error ?? null}
      description={`${errorTask.characterName} · ${errorTask.kind === 'test' ? '测试' : '生成'} x${
        errorTask.params.sampleSteps
      } · ${new Date(errorTask.createdAt).toLocaleString()}`}
      onClose={() => (errorTask = null)}
    />
  {/if}

  {#if changeDialogOpen}
    <VoiceCacheDialog onClose={() => (changeDialogOpen = false)} />
  {/if}
</div>
